def pdf_text(path):
    data = open(path,"rb").read().decode("latin-1","replace")
    out=[]
    for m in re.finditer(r"\((.*?)\)\s*Tj", data, re.S):
        out.append(m.group(1).replace("\\(","(").replace("\\)",")"))
    return "\n".join(out)

def get_xml(path):
    d = open(path, encoding="utf-8").read()
