import os, re, csv, io, json, html
base = "/online1/ycsc_chenkh/hitici_07/deepseek-harness/attached_files/task_10"

def get_body(path, ext):
    if ext==".json":
        return json.load(open(path,encoding="utf-8"))["body"]
    if ext==".csv":
        rows=list(csv.reader(io.StringIO(open(path,encoding="utf-8").read())))
        kv={r[5]:r[6] for r in rows[1:] if len(r)>=6 and r[3]=="metadata"}
        return kv.get("native_record") or kv.get("body")
    if ext==".xml":
        d=open(path,encoding="utf-8").read()
        m=re.search(r"<native-record>(.*?)</native-record>",d,re.S); return m.group(1).strip() if m else None
    if ext==".html":
        d=open(path,encoding="utf-8").read()
        m=re.search(r"</dl><p>(.*?)</p>",d,re.S); return html.unescape(m.group(1)) if m else None
    if ext==".txt":
        d=open(path,encoding="utf-8").read()
        m=re.search(r"NATIVE RECORD\s*\n(.*?)\n\nSOURCE LINEAGE",d,re.S); return m.group(1).strip() if m else None
    if ext==".md":
        d=open(path,encoding="utf-8").read()
        m=re.search(r"## Native record\s*\n(.*?)(\n##|\Z)",d,re.S); return m.group(1).strip() if m else None
    if ext==".eml":
        d=open(path,encoding="utf-8",errors="replace").read()
        return d.split("\n\n",1)[1].split("SOURCE LINEAGE")[0].strip() if "\n\n" in d else None
    if ext==".pdf":
        data=open(path,"rb").read().decode("latin-1","replace")
        out=[m.group(1).replace("\\(","(").replace("\\)",")") for m in re.finditer(r"\((.*?)\)\s*Tj",data,re.S)]
        lines=[l for l in out if l.strip()]
        cap=False; bl=[]
        for l in lines:
            if l.strip()=="NATIVE RECORD": cap=True; continue
            if cap:
                if l.strip()=="SOURCE LINEAGE": break
                bl.append(l)
        return " ".join(bl)

